import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CBxkvBm_.js";const h=JSON.parse('{"title":"Platform Administration & Enterprise Hub Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration.md","filePath":"guide/administration.md"}'),s={name:"guide/administration.md"};function n(r,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="platform-administration-enterprise-hub-guide" tabindex="-1">Platform Administration &amp; Enterprise Hub Guide <a class="header-anchor" href="#platform-administration-enterprise-hub-guide" aria-label="Permalink to &quot;Platform Administration &amp; Enterprise Hub Guide&quot;">​</a></h1><p>The <strong>ModelScript Enterprise Hub</strong> (<code>@modelscript/api</code> and <code>@modelscript/web</code>) provides a self-hostable or cloud-managed control plane for polyglot package management, Git Smart HTTP hosting, OMG SysML v2 / Semantic Web APIs, Slurm HPC simulation offload, operational digital twins, and cryptographically verifiable regulatory compliance.</p><hr><h2 id="_1-administrative-console-role-based-access-control-rbac" tabindex="-1">1. Administrative Console &amp; Role-Based Access Control (RBAC) <a class="header-anchor" href="#_1-administrative-console-role-based-access-control-rbac" aria-label="Permalink to &quot;1. Administrative Console &amp; Role-Based Access Control (RBAC)&quot;">​</a></h2><p>Access to the Platform Administration Console (<code>/admin</code>) and <code>/api/v1/admin/*</code> endpoints is strictly enforced via JWT authentication and role-based middleware (<code>requireAdmin</code>):</p><ul><li><strong><code>admin</code></strong>: Full platform superuser privileges (user moderation, runtime feature flag mutation, system maintenance windows, compute wallet minting, and audit log verification).</li><li><strong><code>moderator</code></strong>: Read/moderation access to public registry packages, flagged comments, and community discussions.</li><li><strong><code>user</code> / Organization Roles (<code>owner</code>, <code>admin</code>, <code>member</code>, <code>billing</code>, <code>viewer</code>)</strong>: Scoped access within <code>/api/v1/organizations/:org</code> namespaces.</li></ul><h3 id="user-account-governance-api-v1-admin-users" tabindex="-1">User &amp; Account Governance (<code>/api/v1/admin/users</code>) <a class="header-anchor" href="#user-account-governance-api-v1-admin-users" aria-label="Permalink to &quot;User &amp; Account Governance (`/api/v1/admin/users`)&quot;">​</a></h3><p>Platform administrators can search, filter, and manage user accounts via the Admin Console or REST API:</p><ul><li><strong>Role Assignment (<code>PATCH /api/v1/admin/users/:id/role</code>)</strong>: Promote or demote accounts between <code>user</code>, <code>moderator</code>, and <code>admin</code>. Self-demotion by the active administrator is blocked to prevent accidental lockout.</li><li><strong>Account Suspension (<code>POST /api/v1/admin/users/:id/suspend</code> &amp; <code>/unsuspend</code>)</strong>: Immediately revokes active JWT refresh tokens, blocks package publishing, and halts running cloud HPC jobs while preserving historical audit trails.</li><li><strong>Platform Telemetry (<code>GET /api/v1/admin/stats</code>)</strong>: Real-time metrics covering total registered users, published package versions, active Co-Simulation sessions, cloud HPC queue depth, and object storage consumption.</li></ul><hr><h2 id="_2-runtime-feature-flags-progressive-rollouts" tabindex="-1">2. Runtime Feature Flags &amp; Progressive Rollouts <a class="header-anchor" href="#_2-runtime-feature-flags-progressive-rollouts" aria-label="Permalink to &quot;2. Runtime Feature Flags &amp; Progressive Rollouts&quot;">​</a></h2><p>ModelScript includes an in-memory and database-backed <strong>Feature Flag Engine</strong> (<code>apps/api/src/services/feature-flag-service.ts</code>) that allows operators to toggle experimental compilers, cloud solvers, or UI capabilities at runtime without redeploying containers.</p><h3 id="flag-evaluation-precedence" tabindex="-1">Flag Evaluation Precedence <a class="header-anchor" href="#flag-evaluation-precedence" aria-label="Permalink to &quot;Flag Evaluation Precedence&quot;">​</a></h3><ol><li><strong>Environment Variable Override</strong>: Setting <code>FEATURE_FLAG_&lt;UPPER_SNAKE_KEY&gt;=true|false</code> (for example, <code>FEATURE_FLAG_WEBGPU_CLOUD_SOLVER=true</code>) overrides database state for deterministic staging/CI configuration.</li><li><strong>Role Gate (<code>allowedRoles</code>)</strong>: If a flag specifies <code>allowedRoles</code> (e.g., <code>[&quot;admin&quot;, &quot;moderator&quot;]</code>), only authenticated users holding one of those roles receive <code>true</code>.</li><li><strong>Deterministic Percentage Rollout (<code>rolloutPercentage</code>)</strong>: When <code>0 &lt; rolloutPercentage &lt; 100</code>, the service computes a deterministic hash over <code>(flagKey, userId)</code> so a given user receives a consistent cohort experience across sessions.</li></ol><h3 id="administrative-flag-endpoints" tabindex="-1">Administrative Flag Endpoints <a class="header-anchor" href="#administrative-flag-endpoints" aria-label="Permalink to &quot;Administrative Flag Endpoints&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Access</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/flags</code></td><td style="text-align:left;">Public / User</td><td style="text-align:left;">Evaluate all feature flags for the current caller&#39;s <code>userId</code> and <code>role</code>.</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/flags</code></td><td style="text-align:left;"><code>admin</code></td><td style="text-align:left;">List all registered feature flags with full rollout metadata, role gates, and environment override states.</td></tr><tr><td style="text-align:left;"><code>PATCH /api/v1/admin/flags/:key</code></td><td style="text-align:left;"><code>admin</code></td><td style="text-align:left;">Dynamically update <code>enabled</code> (<code>boolean</code>), <code>rolloutPercentage</code> (<code>0</code>–<code>100</code>), <code>allowedRoles</code> (<code>string[]</code>), or <code>description</code>, and record an immutable admin audit event.</td></tr></tbody></table><hr><h2 id="_3-enterprise-authentication-sso-2fa-bot-accounts" tabindex="-1">3. Enterprise Authentication, SSO, 2FA &amp; Bot Accounts <a class="header-anchor" href="#_3-enterprise-authentication-sso-2fa-bot-accounts" aria-label="Permalink to &quot;3. Enterprise Authentication, SSO, 2FA &amp; Bot Accounts&quot;">​</a></h2><p>The authentication subsystem (<code>/api/v1/auth</code>, <code>/api/v1/auth/sso</code>, <code>/api/v1/auth/2fa</code>, <code>/api/v1/bots</code>) supports defense-in-depth enterprise identity requirements:</p><ul><li><strong>OpenID Connect (OIDC) &amp; SAML Enterprise SSO (<code>/api/v1/auth/sso</code>)</strong>: Connect Okta, Azure AD / Entra ID, Keycloak, or Google Workspace identity providers with automatic Just-in-Time (JIT) organization provisioning and group-to-role mapping.</li><li><strong>TOTP Two-Factor Authentication (<code>/api/v1/auth/2fa</code>)</strong>: RFC 6238 Time-Based One-Time Password enrollment (QR code provisioning, backup recovery codes, and mandatory 2FA enforcement policies per organization).</li><li><strong>Machine &amp; CI/CD Bot Accounts (<code>/api/v1/bots</code>)</strong>: Provision scoped, non-interactive service accounts bearing <code>ms_bot_*</code> API tokens with granular permissions (<code>package:read</code>, <code>package:publish</code>, <code>cloud:dispatch</code>, <code>mcp:invoke</code>, <code>dhf:export</code>) and automatic token rotation schedules.</li><li><strong>Signed Outbound Webhooks (<code>/api/v1/webhooks</code>)</strong>: Subscribe external CI/CD pipelines to workspace events (<code>package.published</code>, <code>simulation.completed</code>, <code>verification.failed</code>, <code>twin.anomaly_detected</code>) signed with HMAC-SHA256 (<code>X-ModelScript-Signature-256</code>).</li></ul><hr><h2 id="_4-native-git-smart-http-server-content-addressable-registry" tabindex="-1">4. Native Git Smart HTTP Server &amp; Content-Addressable Registry <a class="header-anchor" href="#_4-native-git-smart-http-server-content-addressable-registry" aria-label="Permalink to &quot;4. Native Git Smart HTTP Server &amp; Content-Addressable Registry&quot;">​</a></h2><p>The Hub integrates both a <strong>Git Smart HTTP Backend</strong> and a <strong>Signed Content-Addressable Package Registry</strong>:</p><h3 id="native-git-smart-http-server-git-namespace-project-api-v1-git-server" tabindex="-1">Native Git Smart HTTP Server (<code>/git/:namespace/:project</code> &amp; <code>/api/v1/git-server</code>) <a class="header-anchor" href="#native-git-smart-http-server-git-namespace-project-api-v1-git-server" aria-label="Permalink to &quot;Native Git Smart HTTP Server (`/git/:namespace/:project` &amp; `/api/v1/git-server`)&quot;">​</a></h3><p>Engineers can clone, fetch, branch, and push polyglot model repositories using standard <code>git</code> clients over HTTPS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://hub.example.com/git/aerospace/flight-control.git</span></span></code></pre></div><ul><li>Supports <code>git-upload-pack</code> (<code>GET /info/refs?service=git-upload-pack</code>) and <code>git-receive-pack</code> (<code>POST /git-receive-pack</code>) authenticated via Basic Auth (<code>username</code> + PAT or <code>ms_bot_*</code> token).</li><li>Pre-receive hooks optionally enforce zero-error <code>msx lint</code> checks and Digital Thread correspondence verification before accepting pushes to protected branches.</li></ul><h3 id="cryptographic-package-signing-multi-lens-manifests-api-v1-packages" tabindex="-1">Cryptographic Package Signing &amp; Multi-Lens Manifests (<code>/api/v1/packages</code>) <a class="header-anchor" href="#cryptographic-package-signing-multi-lens-manifests-api-v1-packages" aria-label="Permalink to &quot;Cryptographic Package Signing &amp; Multi-Lens Manifests (`/api/v1/packages`)&quot;">​</a></h3><p>Every package published via <code>msx publish</code> is stored in a SHA-256 Content-Addressable Storage (CAS) blob store and signed with the publisher&#39;s <strong>Ed25519</strong> private key:</p><ul><li><strong>Integrity &amp; Provenance</strong>: <code>msx install --verify-signatures</code> validates both the SHA-256 tarball digest against <code>modelscript.lock</code> and the Ed25519 signature against the registry&#39;s public keyring.</li><li><strong>Multi-Lens Manifest Projection (<code>GET /api/v1/packages/:name/:version?lens=&lt;lens&gt;</code>)</strong>: The registry dynamically projects any <code>modelscript.json</code> package manifest into three industry interoperability schemas on the fly: <ul><li><code>?lens=npm</code>: Standard Node/NPM-compatible package metadata for JavaScript/TypeScript tooling.</li><li><code>?lens=aas</code>: <strong>IDTA Asset Administration Shell (AAS v3.0)</strong> JSON submodel descriptor containing <code>TechnicalData</code> and <code>SimulationModels</code> (FMU) references.</li><li><code>?lens=okh</code>: <strong>DIN SPEC 3105 / OSHWA Open Know-How (OKH v1.0)</strong> hardware manifest exposing CAD/ECAD bill-of-materials, manufacturing files, and SPDX license metadata.</li></ul></li></ul><hr><h2 id="_5-standards-compliant-systems-semantic-web-apis" tabindex="-1">5. Standards-Compliant Systems &amp; Semantic Web APIs <a class="header-anchor" href="#_5-standards-compliant-systems-semantic-web-apis" aria-label="Permalink to &quot;5. Standards-Compliant Systems &amp; Semantic Web APIs&quot;">​</a></h2><p>The Hub natively implements open MBSE and Semantic Web specifications so external enterprise tools can query models without proprietary adapters:</p><table tabindex="0"><thead><tr><th style="text-align:left;">API Surface</th><th style="text-align:left;">Base Path</th><th style="text-align:left;">Standard / Capabilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OMG SysML v2 REST API</strong></td><td style="text-align:left;"><code>/api/v1/sysml2</code> (and root <code>/</code> alias)</td><td style="text-align:left;">Implements the <strong>OMG Systems Modeling API and Services v2.0</strong> specification: <code>/projects</code>, <code>/projects/{id}/commits</code>, <code>/projects/{id}/branches</code>, <code>/projects/{id}/tags</code>, <code>/projects/{id}/commits/{cid}/elements</code>, and <code>/relationships</code>.</td></tr><tr><td style="text-align:left;"><strong>GraphQL Library API</strong></td><td style="text-align:left;"><code>/api/v1/libraries/graphql</code></td><td style="text-align:left;">Strongly typed GraphQL schema for querying packages, Modelica classes, ports, equations, physical units, and dependency graphs in a single round-trip.</td></tr><tr><td style="text-align:left;"><strong>W3C RDF Serialization</strong></td><td style="text-align:left;"><code>/api/v1/libraries/rdf</code></td><td style="text-align:left;">Exports package and workspace ontologies as <code>text/turtle</code>, <code>application/ld+json</code>, or <code>application/n-triples</code>.</td></tr><tr><td style="text-align:left;"><strong>W3C SPARQL 1.1 Endpoint</strong></td><td style="text-align:left;"><code>/api/v1/libraries/sparql</code></td><td style="text-align:left;">Executes SPARQL 1.1 <code>SELECT</code>, <code>CONSTRUCT</code>, and <code>ASK</code> queries with optional OWL 2 RL entailment reasoning over indexed engineering libraries.</td></tr><tr><td style="text-align:left;"><strong>OSLC 3.0 &amp; TRS 3.0</strong></td><td style="text-align:left;"><code>msx oslc serve</code> / <code>/api/v1/threads</code></td><td style="text-align:left;">Exposes OASIS OSLC Requirements (<code>oslc_rm</code>) and Architecture (<code>oslc_am</code>) catalogs with Tracked Resource Set (TRS 3.0) incremental change logs for IBM DOORS Next and Polarion synchronization.</td></tr></tbody></table><hr><h2 id="_6-cloud-slurm-hpc-offload-cae-sweeps-compute-credit-billing" tabindex="-1">6. Cloud Slurm HPC Offload, CAE Sweeps &amp; Compute Credit Billing <a class="header-anchor" href="#_6-cloud-slurm-hpc-offload-cae-sweeps-compute-credit-billing" aria-label="Permalink to &quot;6. Cloud Slurm HPC Offload, CAE Sweeps &amp; Compute Credit Billing&quot;">​</a></h2><p>When engineers run <code>msx simulate --cloud</code> or <code>msx cloud dispatch</code>, the Hub orchestrates containerized batch execution across Slurm HPC clusters or Kubernetes GPU pools:</p><ul><li><strong>Cloud Simulation &amp; CAE Endpoints (<code>/api/v1/cloud</code> &amp; <code>/api/v1/cae</code>)</strong>: <ul><li>Dispatches single-run stiff DAE simulations, multi-thousand-run Monte Carlo ensembles, SU2 CFD runs, and CalculiX FEA jobs to isolated worker nodes.</li><li>Streams live progress events and solver logs via WebSockets (<code>/ws</code>) and persists output trajectories (<code>CSV</code>, <code>Parquet</code>, <code>VTK</code>, <code>FRD</code>) to S3-compatible object storage.</li></ul></li><li><strong>Compute Credit Wallet &amp; Stripe Billing (<code>/api/v1/billing</code>)</strong>: <ul><li>Each user or organization maintains an ACID transactional <strong>Compute Credit Wallet</strong>.</li><li>Job submission places a pre-authorization hold (<code>reserveCredits</code>) based on the requested hardware profile (<code>standard</code>, <code>high-cpu</code>, <code>gpu-a100</code>, <code>slurm-mpi</code>); upon completion or cancellation (<code>msx cloud cancel</code>), exact wall-clock consumption is settled and unused credits are refunded.</li><li>Supports self-service credit top-ups via Stripe Checkout webhooks (<code>/api/v1/billing/webhook</code>) or manual enterprise quota allocation by platform admins.</li></ul></li></ul><hr><h2 id="_7-digital-thread-hash-chained-audit-ledger-operational-digital-twins" tabindex="-1">7. Digital Thread Hash-Chained Audit Ledger &amp; Operational Digital Twins <a class="header-anchor" href="#_7-digital-thread-hash-chained-audit-ledger-operational-digital-twins" aria-label="Permalink to &quot;7. Digital Thread Hash-Chained Audit Ledger &amp; Operational Digital Twins&quot;">​</a></h2><p>For safety-critical industries (aerospace DO-178C, automotive ISO 26262, medical FDA 21 CFR Part 11 / 820, and nuclear IEC 61513), the Hub maintains a tamper-evident digital thread and live twin telemetry pipeline:</p><h3 id="cryptographic-hash-chained-audit-ledger-api-v1-threads-audit-log" tabindex="-1">Cryptographic Hash-Chained Audit Ledger (<code>/api/v1/threads/audit-log</code>) <a class="header-anchor" href="#cryptographic-hash-chained-audit-ledger-api-v1-threads-audit-log" aria-label="Permalink to &quot;Cryptographic Hash-Chained Audit Ledger (`/api/v1/threads/audit-log`)&quot;">​</a></h3><p>Every mutation to a requirement, model equation, TGG alignment link, verification proof, or administrative setting is appended to a PostgreSQL audit ledger where each record $k$ stores:</p><p>$$H_k = \\text{SHA256}\\bigl(H_{k-1} ;|; \\text{timestamp}_k ;|; \\text{actorId}_k ;|; \\text{action}_k ;|; \\text{payloadHash}_k\\bigr)$$</p><p>Operators and external auditors can verify the unbroken integrity of the entire historical chain at any time via the CLI or REST API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify cryptographic hash-chain integrity across the PostgreSQL audit ledger</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export and verify a signed Design History File (DHF) compliance archive</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dhf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release_v1.dhf.md</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dhf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release_v1.dhf.md</span></span></code></pre></div><h3 id="operational-digital-twins-api-v1-twins-api-v1-instances" tabindex="-1">Operational Digital Twins (<code>/api/v1/twins</code> &amp; <code>/api/v1/instances</code>) <a class="header-anchor" href="#operational-digital-twins-api-v1-twins-api-v1-instances" aria-label="Permalink to &quot;Operational Digital Twins (`/api/v1/twins` &amp; `/api/v1/instances`)&quot;">​</a></h3><ul><li><strong>Asset Instance Registry (<code>/api/v1/instances</code>)</strong>: Tracks serialized physical assets in the field (e.g., tail numbers, inverter serial IDs, or battery packs) bound to specific immutable commits of their ModelScript digital twin.</li><li><strong>Live Telemetry &amp; Drift Detection (<code>/api/v1/twins</code>)</strong>: Ingests time-series sensor telemetry via REST/WebSockets, executes an online Extended Kalman Filter (EKF) / moving-horizon observer against the compiled WASM DAE arena, and triggers automated alerts when physical parameter drift or residual anomalies exceed safety thresholds.</li></ul><hr><h2 id="_8-hosted-mcp-sse-gateway-api-v1-mcp" tabindex="-1">8. Hosted MCP SSE Gateway (<code>/api/v1/mcp</code>) <a class="header-anchor" href="#_8-hosted-mcp-sse-gateway-api-v1-mcp" aria-label="Permalink to &quot;8. Hosted MCP SSE Gateway (`/api/v1/mcp`)&quot;">​</a></h2><p>Enterprise teams can connect cloud AI agents and internal copilot orchestrators directly to the Hub&#39;s <strong>Hosted Model Context Protocol (MCP) Gateway</strong>:</p><ul><li><strong><code>GET /api/v1/mcp/sse</code></strong>: Authenticates via Bearer token (<code>JWT</code> or <code>ms_bot_*</code>) and opens a server-sent events transport session.</li><li><strong><code>POST /api/v1/mcp/messages</code></strong>: Dispatches any of the <a href="./../reference/mcp-and-ide.html">29 MCP engineering tools</a> inside sandboxed worker isolates with automatic compute credit metering and full audit-ledger logging of every AI tool invocation.</li></ul>',52)])])}const u=t(s,[["render",n]]);export{h as __pageData,u as default};
